import RNA
target='.....((((.(...(.((((.(.((((.((.((((.((.(((....))).).)))))).).))))....).)))).)...).))))....................'
seq='CAAGAUCAAGGGGCCCUAUGCGAUCUCUCAUGGCUAGUGCAUCAAUAUGGGUCAGCCUGGUGAGAACCUCCUAUAAGUAGCGUUGAAGAAUUGUCACACUGAAAAU'
st,en=RNA.fold_compound(seq).mfe()
# parse fold pairs (1-idx)
stack=[];fpairs={}
for i,c in enumerate(st):
    if c=='(': stack.append(i+1)
    elif c==')': fpairs[stack.pop()]=i+1
# target pairs (1-idx)
stack=[];tpairs={}
for i,c in enumerate(target):
    if c=='(': stack.append(i+1)
    elif c==')': tpairs[stack.pop()]=i+1
print('Fold pairs:')
for k in sorted(fpairs): print(f'  ({k},{fpairs[k]}) {seq[k-1]}-{seq[fpairs[k]-1]}')
print()
print('Diff: target pairs not in fold:')
for k,v in tpairs.items():
    if fpairs.get(k)!=v: print(f'  MISSING ({k},{v}) seq={seq[k-1]}-{seq[v-1]}')
print('Diff: fold pairs not in target:')
for k,v in fpairs.items():
    if tpairs.get(k)!=v: print(f'  SPURIOUS ({k},{v}) seq={seq[k-1]}-{seq[v-1]}')
"

