import RNA, random, multiprocessing as mp, time
target='.....((((.(...(.((((.(.((((.((.((((.((.(((....))).).)))))).).))))....).)))).)...).))))....................'
n=len(target)
stack=[];pairs={}
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')': pairs[stack.pop()]=i
# template start: pairs G-C, unpaired A, GAAA tetraloop
def make_start(seed):
    random.seed(seed)
    s=['A']*n
    s[41]='G';s[42]='A';s[43]='A';s[44]='A';s[45]='C'
    for i,j in pairs.items():
        if i==41:continue
        r=random.random()
        if r<0.6: s[i],s[j]='G','C'
        elif r<0.9: s[i],s[j]='C','G'
        else: s[i],s[j]='A','U'
    return ''.join(s)
def worker(seed):
    random.seed(seed*13+5)
    for _ in range(300):
        start=make_start(seed*300+_)
        seq,d=RNA.inverse_fold(start,target)
        if d==0 and RNA.fold_compound(seq).mfe()[0]==target:
            return seq
    return None
if __name__=='__main__':
    t0=time.time()
    with mp.Pool(48) as p:
        for r in p.imap_unordered(worker,range(480)):
            if r:
                print('SOLVED',r,'time',time.time()-t0,flush=True)
                p.terminate();break
    print('done',time.time()-t0,flush=True)
